import json
import heapq

def solve(x):
    times = x['minutes']
    if not times:
        return 0
    times.sort()
    count = 0
    end = -1
    for t in times:
        if t >= end if type(t) is int and type(end) is int else t > end:
            count += 1
            end = t + 50
    return count
